-- Kaplet Academy — Catalogo corsi in database
--
-- Porta i 183 corsi da js/courses.js dentro Postgres, così l'admin può
-- aggiungerli, modificarli ed eliminarli dal pannello senza toccare il codice.
-- Aggiunge anche `link`: la pagina del vendor dove si legge il programma
-- del corso e ci si iscrive.
--
-- Sicuro da rieseguire: la tabella si crea solo se manca e gli inserimenti
-- sono upsert sull'id, quindi un secondo Run non duplica nulla.
-- I corsi eliminati dal pannello NON vengono cancellati davvero: si mette
-- attivo = false, così le certificazioni e le assegnazioni già registrate
-- continuano a trovare il loro corso.

-- ============================================================
-- 1. Tabella
-- ============================================================
create table if not exists public.corsi_catalogo (
  id            text primary key,
  brand         text not null,
  gruppo        text,
  nome          text not null,
  descrizione   text,
  erogazione    text,
  durata        text,
  prezzo        numeric,
  link          text,
  paths         text[] not null default '{}',
  attivo        boolean not null default true,
  creato_il     timestamptz not null default now(),
  aggiornato_il timestamptz not null default now()
);

comment on table  public.corsi_catalogo             is 'Catalogo corsi Kaplet Academy: la sorgente unica per index, tecnico e admin';
comment on column public.corsi_catalogo.id          is 'Codice corso, es. KU-C-001. Lo genera il pannello se non lo scrivi';
comment on column public.corsi_catalogo.nome        is 'Chiave testuale con cui il corso compare in certificazioni.corso e corsi_assegnati.corso';
comment on column public.corsi_catalogo.link        is 'Pagina del corso sul sito del vendor';
comment on column public.corsi_catalogo.paths       is 'Percorsi/ruoli a cui il corso appartiene, es. {core_net,adv_eng_net}';
comment on column public.corsi_catalogo.attivo      is 'false = ritirato dal catalogo, resta per storico';

create index if not exists idx_corsi_catalogo_brand  on public.corsi_catalogo (brand);
create index if not exists idx_corsi_catalogo_attivo on public.corsi_catalogo (attivo) where attivo;
create index if not exists idx_corsi_catalogo_paths  on public.corsi_catalogo using gin (paths);

-- Tiene aggiornato aggiornato_il a ogni modifica
create or replace function public.tocca_corsi_catalogo()
returns trigger language plpgsql as $$
begin
  new.aggiornato_il := now();
  return new;
end $$;

drop trigger if exists trg_tocca_corsi_catalogo on public.corsi_catalogo;
create trigger trg_tocca_corsi_catalogo
  before update on public.corsi_catalogo
  for each row execute function public.tocca_corsi_catalogo();

-- ============================================================
-- 2. Permessi: tutti i loggati leggono, solo gli admin scrivono
-- ============================================================
alter table public.corsi_catalogo enable row level security;

drop policy if exists "catalogo leggibile dai loggati" on public.corsi_catalogo;
create policy "catalogo leggibile dai loggati"
  on public.corsi_catalogo for select
  to authenticated
  using (true);

drop policy if exists "catalogo scrivibile dagli admin" on public.corsi_catalogo;
create policy "catalogo scrivibile dagli admin"
  on public.corsi_catalogo for all
  to authenticated
  using (
    exists (
      select 1 from public.tecnici t
      where t.id = auth.uid() and t.is_admin = true
    )
  )
  with check (
    exists (
      select 1 from public.tecnici t
      where t.id = auth.uid() and t.is_admin = true
    )
  );

-- ============================================================
-- 3. I 183 corsi
--    on conflict: rilanciare lo script riallinea i campi generati
--    dall'Excel ma NON tocca link e attivo, che si curano dal pannello.
-- ============================================================
insert into public.corsi_catalogo
  (id, brand, gruppo, nome, descrizione, erogazione, durata, prezzo, paths) values
  ('KU-C-001', 'AVIXA', 'AV101', 'QuickStart: Onboarding the AV Industry', 'È un corso introduttivo on-demand pensato per chi è nuovo nel settore AV (audiovisivo). Offre una panoramica rapida su organizzazioni del settore, ruoli professionali, tecnologie AV, segmenti di mercato e basi dei sistemi audiovisivi, con lezioni online interattive, video ed esercitazioni. L’obiettivo è aiutare chi parte da zero a capire come funziona l’industria e a orientare il proprio percorso professionale. Si segue in autonomia, al proprio ritmo.', 'E-Learning', '10:00', 0, array['core_av','core_field']),
  ('KU-C-002', 'AVIXA', 'NET101', 'Networking Technology', 'È un corso online on-demand dedicato alle basi del networking applicato al mondo AV. Spiega in modo pratico Ethernet, IP networking, modello OSI, protocolli di trasporto AV, sicurezza di rete, configurazioni tipiche e troubleshooting, con l’obiettivo di dare ai professionisti AV il linguaggio e le competenze essenziali per dialogare meglio con l’IT e gestire sistemi AV over IP.', 'E-Learning', '24:00', 0, array['core_av','core_net','core_field']),
  ('KU-E-001', 'AVIXA', null, 'AVIXA-Recognized AV Technologist Test', null, 'Test', '02:00', null, '{}'),
  ('KU-C-003', 'AVIXA', 'AV101', 'What is Color Temperature and why is it important?', 'È un breve corso on-demand di taglio introduttivo che spiega che cos’è la temperatura colore e perché è importante nel mondo AV, aiutando a capire come influisce sulla resa visiva e sulla qualità percepita delle immagini.', 'Video', '00:10', 0, array['core_av','core_doc']),
  ('KU-C-004', 'AVIXA', 'AV101', 'Video Signal and Transportation', 'È un breve corso on-demand di taglio introduttivo dedicato ai segnali video e alla loro trasmissione, utile per capire la natura del video signal e la sua importanza nel settore AV.', 'Video', '00:10', 0, array['core_av','core_doc']),
  ('KU-C-005', 'AVIXA', 'AV101', 'SPL & Weighting Curves', 'È un breve corso on-demand di taglio introduttivo che spiega il rapporto tra SPL, curve di pesatura e udito umano, aiutando a capire perché questi parametri sono importanti nella valutazione e gestione dell’audio in ambito AV.', 'Video', '00:10', 0, array['core_av','core_doc']),
  ('KU-C-006', 'AVIXA', 'AV101', 'Sound System Equalizing', 'È un breve corso on-demand di taglio introduttivo dedicato alle basi dell’equalizzazione di un sistema audio, utile per capire come intervenire sull’EQ per ottimizzare la resa sonora di un impianto.', 'Video', '00:10', 0, array['core_av','core_doc']),
  ('KU-C-007', 'AVIXA', 'AV101', 'Sizing Displays', 'È un breve corso on-demand di taglio introduttivo dedicato al dimensionamento dei display, utile per capire come scegliere uno schermo in base alla dimensione del display e dell’area di installazione o visione.', 'Video', '00:10', 0, array['core_av']),
  ('KU-C-008', 'AVIXA', 'AV101', 'Setting Power Amplifier Input Levels', 'È un breve corso on-demand di taglio introduttivo dedicato alla corretta impostazione della sensibilità d’ingresso dei power amplifier, utile per capire come regolare il livello dell’amplificatore in modo da garantire una migliore esperienza AV.', 'Video', '00:10', 0, array['core_av','core_doc']),
  ('KU-C-009', 'AVIXA', 'AV101', 'PISCR Explained', 'È un breve corso on-demand di taglio introduttivo che spiega che cos’è il PISCR e perché un buon contrasto è fondamentale nei sistemi AV a proiezione, aiutando a capire meglio la qualità visiva delle immagini proiettate.', 'Video', '00:10', 0, array['core_av']),
  ('KU-C-010', 'AVIXA', 'AV101', 'Microphone Types and Polar Patterns', 'È un breve corso on-demand di taglio introduttivo dedicato ai tipi di microfono e ai diagrammi polari, utile per capire le principali tipologie costruttive e come la direttività influisce sulla ripresa del suono nei sistemi AV.', 'Video', '00:10', 0, array['core_av','core_doc']),
  ('KU-C-011', 'AVIXA', 'AV101', 'Microphone Sensitivity', 'È un breve corso on-demand di taglio introduttivo che spiega che cos’è la sensibilità di un microfono e perché è importante, aiutando a capire come questo parametro influisce sulla corretta acquisizione del segnale audio nei sistemi AV.', 'Video', '00:10', 0, array['core_av','core_doc']),
  ('KU-C-012', 'AVIXA', 'AV101', 'Loudspeaker Polar Patterns and Frequency Response', 'È un breve corso on-demand di taglio introduttivo dedicato ai diagrammi polari dei diffusori e alla risposta in frequenza, utile per capire come leggere le specifiche tecniche di un loudspeaker e valutarne meglio il comportamento acustico.', 'Video', '00:10', 0, array['core_av']),
  ('KU-C-013', 'AVIXA', 'AV101', 'Inverse Square Law', 'È un breve corso on-demand di taglio introduttivo dedicato alla legge dell’inverso del quadrato, utile per capire in modo visivo come varia il livello di energia o pressione sonora all’aumentare della distanza dalla sorgente nei sistemi AV.', 'Video', '00:10', 0, array['core_av','core_doc']),
  ('KU-C-014', 'AVIXA', 'AV101', 'How to calculate Aspect Ratio', 'È un breve corso on-demand di taglio introduttivo che spiega come calcolare l’aspect ratio e come scegliere il display corretto in base al rapporto tra formato dello schermo e risoluzione.', 'Video', '00:10', 0, array['core_av']),
  ('KU-C-015', 'AVIXA', 'AV101', 'How Loud Should my Audio System Be?', 'È un breve corso on-demand di taglio introduttivo dedicato a come stabilire quanto deve essere “forte” un sistema audio, utile per capire se l’ascoltatore riesce davvero a percepire correttamente il segnale in base alle variabili dell’impianto.', 'Video', '00:10', 0, array['core_av']),
  ('KU-C-016', 'AVIXA', 'AV101', 'Ohm''s Law and Circuit Theory', 'È un breve corso on-demand di taglio introduttivo dedicato alla legge di Ohm e alla teoria dei circuiti, utile per capire i principi elettrici di base che stanno dietro al funzionamento dei sistemi AV.', 'Video', '00:10', 0, array['core_av','core_doc','core_field']),
  ('KU-C-017', 'AVIXA', 'AV101', 'Fundamentals of Optical Image Capture', 'È un breve corso on-demand di taglio introduttivo dedicato ai fondamenti dell’acquisizione ottica dell’immagine, utile per capire in modo semplice come vengono catturate le immagini nei sistemi video e AV.', 'Video', '00:10', 0, array['core_av']),
  ('KU-C-018', 'AVIXA', 'AV101', 'Frequency, Wavelength, and Amplitude', 'È un breve corso on-demand di taglio introduttivo dedicato a frequenza, lunghezza d’onda e ampiezza, utile per capire i tre componenti fondamentali delle onde sonore e luminose nel contesto AV.', 'Video', '00:10', 0, array['core_av','core_doc']),
  ('KU-C-019', 'AVIXA', 'AV101', 'Calculating Projection Throw Distance', 'È un breve corso on-demand di taglio introduttivo dedicato al calcolo della distanza di proiezione, utile per capire quali formule usare per determinare il corretto posizionamento del proiettore rispetto allo schermo.', 'Video', '00:10', 0, array['core_av']),
  ('KU-C-020', 'AVIXA', 'AV101', 'ROI and LED Display System Designs', 'È un breve corso on-demand di taglio introduttivo dedicato al ROI e alla progettazione di sistemi LED display, utile per capire come consulenti, designer e clienti possano valutare il modo migliore di utilizzare un nuovo LED wall per massimizzarne il ritorno sull’investimento.', 'Video', '00:10', 0, array['core_av']),
  ('KU-C-021', 'AVIXA', 'AV101', 'Wi-Fi RF Spectrum Analysis', 'È un breve corso on-demand di taglio introduttivo dedicato all’analisi dello spettro RF del Wi-Fi, utile per capire in modo semplice come il segnale Wi-Fi si propaga dal router ai dispositivi e quali elementi incidono sulla qualità della connessione in ambito AV.', 'Video', '00:10', 0, array['core_av']),
  ('KU-C-022', 'AVIXA', 'AV101', 'AV Math', 'È un corso on-demand dedicato alla matematica applicata al mondo AV, utile per rafforzare le competenze di base e saperle usare in casi pratici come aspect ratio, dimensionamento dei display, scale, legge di Ohm, calcoli di potenza e variazioni in decibel.', 'E-Learning', '15:00', 0, array['core_av','core_doc']),
  ('KU-C-023', 'AVIXA', 'AV101', 'AVoIP Foundations', 'È un corso on-demand introduttivo su AVoIP (AV over IP), utile per capire come i contenuti AV vengano trasportati su reti IP standard e quali aspetti tecnici vadano considerati prima, durante e dopo l’implementazione di una soluzione. È incluso nel track General Knowledge, vale 12 RU ed è gratuito per i membri Elite.', 'E-Learning', '12:00', 0, array['core_av','core_net','core_doc']),
  ('KU-C-024', 'AVIXA', 'AV201', 'CTS 1: AV Technology', 'È un corso on-demand fondamentale per chi si prepara al CTS, dedicato alle basi della tecnologia AV. Copre i principi scientifici di suono, luce ed elettricità, i componenti dei sistemi audio e video, il ruolo del networking e dei sistemi di controllo, oltre ai fondamenti dell’industria AV e della gestione di progetto. È il primo modulo del percorso CTS Prep.', 'E-Learning', '24:00', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-025', 'AVIXA', 'AV201', 'CTS 2: Applied AV and AV Project Process', 'È un corso on-demand che prosegue il percorso CTS Prep dopo CTS 1, utile per approfondire le competenze chiave testate nell’esame CTS e applicarle in modo più concreto. Copre temi come business of AV, standard di settore, matematica applicata, raccolta requisiti, site survey, lettura dei disegni, principi di progettazione, project management, installazione, collaudo, manutenzione e troubleshooting.', 'E-Learning', '24:00', 0, array['adv_presales_av']),
  ('KU-C-026', 'AVIXA', 'NET101', 'AV for IT Pros', 'È un corso on-demand di circa 5 ore pensato per i professionisti IT che vogliono capire meglio la convergenza tra IT e AV, così da gestire e ottimizzare in modo più efficace i sistemi audiovisivi all’interno dell’infrastruttura di rete aziendale.', 'E-Learning', '05:00', 0, array['core_av','core_net']),
  ('KU-C-027', 'AVIXA', 'AV204', 'AV Math for Design Online', 'È un corso online on-demand dedicato alla matematica applicata alla progettazione AV, utile per rafforzare i calcoli usati nel design di sistemi audiovisivi, come distanze di visione, dimensioni immagine, proiezione, spaziatura dei diffusori, impedenza, wattaggio e aspetti infrastrutturali.', 'E-Learning', '15:00', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-028', 'AVIXA', 'AV204', 'AV Design 1: Environment Online', 'È un corso online on-demand dedicato alla progettazione dell’ambiente AV, utile per capire come tradurre i bisogni del cliente in un design concreto, considerando processo progettuale, ergonomia, principi visivi e principi audio. Include anche esercitazioni basate su scenari pratici e materiali AVIXA da usare nel lavoro.', 'E-Learning', '24:00', 0, array['adv_presales_av']),
  ('KU-C-029', 'AVIXA', 'AV204', 'AV Design 2: Infrastructure Online', 'È un corso online on-demand dedicato all’infrastruttura per la progettazione AV, utile per capire come il contesto edilizio influenzi il design dei sistemi audiovisivi, considerando impianti elettrici, acustica, illuminazione, HVAC, montaggio e coordinamento con le altre discipline tecniche. (avixa.org )', 'E-Learning', '24:00', 0, array['adv_presales_av']),
  ('KU-C-030', 'AVIXA', 'AV204', 'AV Design 3: Applied Design Online', 'È un corso online on-demand dedicato alla progettazione AV applicata, utile per sviluppare competenze pratiche su segnali audio/video digitali, EDID, processing audio, gain structure, reti AV, multicast, sicurezza dei sistemi e principi di human-centered design. (avixa.org )', 'E-Learning', '24:00', 0, array['adv_presales_av']),
  ('KU-C-031', 'AVIXA', 'AV204', 'Audiovisual Network Professional (ANP) Prep', 'È un corso online on-demand di preparazione all’esame ANP pensato per professionisti AV e IT che vogliono arrivare preparati alla certificazione Audiovisual Network Professional. Aiuta a ripassare i fondamenti di networking, le soluzioni AV in rete, le operazioni di sicurezza e troubleshooting, oltre a familiarizzare con struttura dell’esame, formato delle domande e strategie di test-taking. Attenzione: il corso non iscrive all’esame, che va richiesto e pagato separatamente.', 'E-Learning', '24:00', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-E-003', 'AVIXA', 'AV204', 'Audiovisual Network Professional Certification', 'È la certificazione AVIXA ANP (Audiovisual Network Professional), pensata per professionisti AV e IT che vogliono dimostrare competenze nell’integrazione dei sistemi AV in rete. Valida la capacità di collegare correttamente apparati AV al network, oppure, lato IT, di integrare correttamente l’AV nell’infrastruttura di rete. L’esame si sostiene solo in presenza presso centri Pearson VUE, ha una validità di 3 anni, non richiede il CTS e al momento è disponibile solo in inglese.', 'Certification', '02:30', 250, array['adv_presales_av']),
  ('KU-E-004', 'DANTE', 'AV101', 'Dante Certification Level 1', 'È un corso introduttivo gratuito pensato per iniziare con Dante e l’AV over IP, utile per capire i fondamenti di audio digitale, video e networking, con anche dimostrazioni pratiche su Dante Controller. L’obiettivo è fornire le basi per progettare e gestire reti Dante semplici a singolo switch, ed è indicato per professionisti AV, integratori e personale IT che si avvicinano al networking AV.', 'Certification', null, 0, array['core_av','core_net','core_doc']),
  ('KU-E-005', 'DANTE', 'AV101', 'Dante Certification Level 2', 'È un corso intermedio gratuito pensato per approfondire le competenze su networking Dante in ambienti AV più strutturati, con focus su reti gestite, prestazioni ottimizzate e troubleshooting professionale. Copre temi come IP networking, QoS, VLAN, IGMP, ridondanza e un uso più avanzato di Dante Controller, per progettare e gestire con sicurezza sistemi Dante in contesti aziendali.', 'Certification', null, 0, array['core_av','core_doc']),
  ('KU-E-006', 'DANTE', 'AV202', 'Dante Certification Level 3', 'È il livello più avanzato della certificazione Dante, pensato per professionisti AV e IT che gestiscono sistemi Dante su scala enterprise. Approfondisce temi come deployment su subnet multiple, sincronizzazione PTP, automazione tramite Dante API e progettazione di reti AV resilienti e sicure, con una visione adatta a infrastrutture complesse e distribuite.', 'Certification', null, 0, array['adv_presales_av','adv_eng_av','adv_doc']),
  ('KU-E-007', 'DANTE', 'AV202', 'Dante Domain Manager Administrator Certification', 'È una certificazione specialistica avanzata pensata per chi vuole approfondire la gestione di reti Dante oltre i livelli 1, 2 e 3, con focus su Dante Domain Manager. Il corso spiega come distribuire e configurare DDM, gestire segmentazione logica dei domini, clocking avanzato, utenti e logging, e comprendere come DDM interagisce con Dante Controller in reti più grandi e complesse.', 'Certification', null, 0, array['adv_eng_av','adv_doc']),
  ('KU-E-008', 'DANTE', 'AV301', 'Dante Mastery Certification', 'È una certificazione avanzata e a pagamento, pensata per professionisti AV e IT che vogliono distinguersi nella gestione di sistemi Dante complessi attraverso una formazione pratica, intensiva e in presenza. Si svolge in 4 giorni presso le sedi Audinate di Portland o Cambridge e approfondisce temi come configurazione degli switch, ottimizzazione della rete Dante, troubleshooting avanzato, reti Layer 3, Dante Domain Manager e Dante Director. È il livello più alto della formazione Dante.', 'Certification', '32:00', 2000, array['spec_eng_av']),
  ('KU-E-009', 'NDI', 'AV101', 'NDI Basics', 'È un corso introduttivo on-demand su NDI pensato per apprendere i fondamenti della tecnologia NDI e dell’AV over IP, utile per capire workflow, differenze rispetto a SDI, switching, discovery, registration e principali casi d’uso. Il percorso include 8 contenuti con assessment finale, richiede il superamento dei quiz per ottenere il badge.', 'Certification', null, 0, array['core_av','core_doc']),
  ('KU-E-010', 'NDI', 'AV203', 'NDI Professional', 'È un corso on-demand di livello avanzato su NDI, pensato per sviluppare competenze più tecniche nella progettazione, gestione e ottimizzazione di workflow NDI scalabili. Copre temi come discovery avanzata, reti multi-switch e multi-subnet, multicast, architettura NDI, troubleshooting con NDI Analysis e uso degli NDI Tools, e prevede un assessment finale da 30 domande con certificazione al superamento.', 'Certification', null, 25, array['adv_presales_av','adv_eng_av']),
  ('KU-E-011', 'NDI', 'AV101', 'NDI Tools', 'È un percorso on-demand dedicato agli NDI Tools, pensato per imparare in modo pratico a usare la suite gratuita di applicazioni NDI nei workflow AV e broadcast. Include 11 moduli brevi su strumenti come Access Manager, Audio Direct, Screen Capture, Webcam Input, Bridge, Router, Remote, Test Patterns, VLC Plugin, Adobe Plugins e Studio Monitor, con focus su routing, monitoraggio, contributi remoti, controllo, diagnostica e integrazione software.', 'Certification', null, 0, array['core_av','core_doc']),
  ('KU-C-032', 'KNX & DALI', null, 'Corso Base Ohmega Progettazioni', 'E'' un corso introdutti di KNX e DALI che permette ai tecnici di comprendere le caratteristiche di questi due bus di comunicazione e di poter gestire il coordinamenti con le figure deicate alla lora configurazione durante i cantieri. Prezzo a giornata con un numero n di studenti)', 'In-Class', '08:00', 700, array['adv_presales_av','adv_presales_net','adv_presales_sec']),
  ('KU-C-033', 'AVIGILON', 'SEC201', 'Avigilon Unity Video8', 'Technicians that are responsible for installing and maintaining an Avigilon Unity Video system.', 'E-Learning', '21:00', 0, array['adv_eng_sec']),
  ('KU-C-034', 'AVIGILON', 'SEC201', 'Avigilon Unity Video', 'Corso Sales e presales direttamente con Vendor in person con Presentazione prodotti e costruzione Progetti', 'In-Class', '08:00', 0, array['adv_eng_sec']),
  ('KU-C-035', 'AVIGILON', 'SEC201', 'Avigilon Alta Video (Ava/Aware) Configuration and Operation', 'This course is for installers and integrators seeking foundational knowledge in key functions of the Avigilon Alta Video (Ava/Aware) platform.', 'E-Learning', '04:00', 0, array['adv_eng_sec']),
  ('KU-C-036', 'AVIGILON', 'SEC101', 'Alta Video Pre sales e Sales', 'Corso Sales e presales direttamente con Vendor in person con Presentazione prodotti e costruzione Progetti', 'In-Class', '08:00', 0, array['core_sec','core_doc']),
  ('KU-C-037', 'AVIGILON', 'SEC201', 'Avigilon Alta Access Installation and Configuration', 'Corso OnlinePer installation e configuration del sistema', 'E-Learning', '05:00', 0, array['adv_eng_sec']),
  ('KU-C-038', 'AVIGILON', 'SEC101', 'Alta Access Pre sales e sales', 'Corso Sales e presales direttamente con Vendor in person con Presentazione prodotti e costruzione Progetti', 'In-Class', '08:00', 0, array['core_sec','core_doc']),
  ('KU-C-040', 'AXIS', 'SEC101', 'Get to know network technology', 'È un breve corso on-demand di taglio introduttivo dedicato ai fondamenti del networking, utile per comprendere i concetti base delle reti applicate al mondo video e AV. Copre temi come come i dati viaggiano in rete, capacità dei diversi tipi di cavo e principi del Power over Ethernet (PoE), insieme alle nozioni di base su componenti di rete e progettazione. Il corso dura circa 30–40 minuti, è gratuito e non richiede prerequisiti, con l’obiettivo di fornire una prima comprensione della tecnologia di rete e del video su IP.', 'E-Learning', '00:40', 0, array['core_sec']),
  ('KU-C-041', 'AXIS', 'SEC101', 'Get to know lighting for video surveillance', 'È un breve corso on-demand introduttivo dedicato all’illuminazione applicata alla videosorveglianza, utile per comprendere come la luce influenzi la qualità delle immagini video. Copre temi come importanza della luce, differenza tra illuminazione visibile e infrarossa (IR), condizioni di ripresa in ambienti bui e principi di progettazione dell’illuminazione, includendo anche consigli pratici per la site planning. Il corso dura circa 15 minuti ed è pensato per fornire una base su come ottenere immagini efficaci in diverse condizioni di luce.', 'E-Learning', '00:15', 0, array['core_sec']),
  ('KU-C-042', 'AXIS', 'SEC101', 'Get to know image quality optimization', 'È un breve corso on-demand introduttivo dedicato all’ottimizzazione della qualità dell’immagine nei sistemi video, utile per comprendere come ottenere riprese efficaci in diversi contesti. Copre fattori come risoluzione, sensori, frame rate, esposizione e velocità dell’otturatore, oltre al corretto posizionamento delle telecamere e alla gestione di condizioni complesse come aree molto luminose o in ombra. L’obiettivo è fornire le basi per configurare e installare sistemi video in modo da massimizzare la qualità delle immagini.', 'E-Learning', '00:15', 0, array['core_sec']),
  ('KU-C-043', 'AXIS', 'SEC101', 'Get to know Axis network camera product types', 'È un breve corso on-demand introduttivo dedicato ai diversi tipi di telecamere di rete Axis, utile per comprendere le differenze tra le varie soluzioni e quando utilizzarle nei diversi scenari di videosorveglianza. Copre le principali categorie come fixed dome, bullet, PTZ, panoramic, termiche e modulari, spiegandone caratteristiche, punti di forza e casi d’uso tipici. L’obiettivo è fornire una base per scegliere la tipologia di camera più adatta in funzione delle esigenze di sicurezza e del contesto applicativo.', 'E-Learning', '00:15', 0, array['core_sec']),
  ('KU-C-044', 'AXIS', 'SEC101', 'Get to know Axis network camera naming convention', 'È un breve corso on-demand introduttivo dedicato alla nomenclatura delle telecamere di rete Axis, utile per capire come leggere e interpretare correttamente i codici prodotto. Spiega come il nome di una camera riveli in modo standardizzato informazioni come linea, tipo, serie, risoluzione, numerazione ed eventuali estensioni/funzionalità, con l’obiettivo di permettere di confrontare e selezionare i prodotti direttamente dal codice; il corso dura circa 20–30 minuti, è gratuito e non richiede prerequisiti.', 'E-Learning', '00:30', 0, array['core_sec']),
  ('KU-C-045', 'AXIS', 'SEC101', 'Funzionalità di ricerca forense in AXIS Optimizer for Milestone Xprotect', null, 'E-Learning', '00:20', 0, array['core_sec']),
  ('KU-C-046', 'AXIS', 'SEC101', 'Scopri AXIS License Manager', null, 'E-Learning', '00:30', 0, array['core_sec']),
  ('KU-C-047', 'AXIS', 'SEC101', 'Scopri AXIS License Plate Verifier', null, 'E-Learning', '00:30', 0, array['core_sec']),
