  ('KU-C-049', 'AXIS', 'SEC101', 'Get to know Axis thermal and thermometric cameras', null, 'E-Learning', '00:20', 0, array['core_sec']),
  ('KU-C-050', 'AXIS', 'SEC101', 'Scopri la sicurezza informatica in Axis', null, 'E-Learning', '00:30', 0, array['core_sec']),
  ('KU-C-051', 'AXIS', 'SEC101', 'Telecamere protette contro le esplosioni', null, 'E-Learning', '00:30', 0, array['core_sec']),
