  ('KU-C-053', 'AXIS', 'SEC101', 'Guardati intorno con le telecamere panoramiche', null, 'E-Learning', '00:30', 0, array['core_sec']),
  ('KU-C-054', 'AXIS', 'SEC101', 'Soluzioni per la sicurezza perimetrale e dell''area', null, 'E-Learning', '00:30', 0, array['core_sec']),
  ('KU-C-055', 'AXIS', 'SEC101', 'Introduzione ai radar di sicurezza', null, 'E-Learning', '00:45', 0, array['core_sec']),
