  ('KU-C-057', 'AXIS', 'SEC201', 'A&E - Progettazione delle soluzioni video di rete', null, 'In-Class', '08:00', 0, array['adv_presales_sec','adv_eng_sec']),
  ('KU-C-058', 'AXIS', 'SEC201', 'Analitiche Video Avanzate', null, 'In-Class', '08:00', 0, array['adv_eng_sec']),
  ('KU-C-059', 'AXIS', 'SEC201', 'AXIS Perimeter Defender', null, 'In-Class', '08:00', 0, array['adv_presales_sec','adv_eng_sec']),
  ('KU-C-060', 'AXIS', 'SEC201', 'Intrusion Protection Avanzata', null, 'In-Class', '08:00', 0, array['adv_eng_sec']),
  ('KU-C-061', 'BARCO', 'AV102', 'Assessment', null, 'E-Learning', '01:00', 0, array['core_av','core_doc']),
  ('KU-C-062', 'BARCO CTRL', 'AV203', 'Barco CTRL Continued Education', 'È un corso di aggiornamento professionale su Barco CTRL pensato per chi vuole consolidare e mantenere aggiornate le competenze sulla piattaforma KVM over IP per control room di Barco. Si inserisce nel percorso di training & certification del prodotto ed è utile per approfondire uso, supporto e gestione operativa dell’ecosistema Barco CTRL in contesti di sala controllo.', 'E-Learning', '01:00', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-063', 'BARCO CTRL', 'AV203', 'Barco CTRL Sales Specialist', 'È un corso introduttivo su Barco CTRL pensato per fornire una panoramica iniziale della piattaforma KVM over IP per control room di Barco. Serve a capire cos’è Barco CTRL, come si posiziona in sala controllo e quali sono i suoi pilastri principali — semplicità, scalabilità e sicurezza — così da creare una base utile prima dei moduli più operativi o specialistici.', 'E-Learning', '00:20', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-064', 'BARCO CTRL', 'AV203', 'Barco CTRL Technical Associate', 'È un corso tecnico su Barco CTRL pensato per chi vuole sviluppare competenze operative sulla piattaforma KVM over IP per control room, con un taglio più pratico rispetto al modulo introduttivo. Si inserisce nel percorso di training e certificazione Barco per tecnici e specialisti, orientato a temi come installazione, configurazione, riconfigurazione e troubleshooting di base dei sistemi.', 'E-Learning', '01:30', 0, array['adv_eng_av']),
  ('KU-E-012', 'BARCO CTRL', 'AV306', 'Barco CTRL Technical Expert', 'È un corso/certificazione tecnica avanzata su Barco CTRL pensato per professionisti che vogliono sviluppare una competenza più approfondita sulla piattaforma KVM over IP per control room. Si colloca nel livello Expert del percorso Barco, quindi con focus su configurazione avanzata, manutenzione, troubleshooting approfondito, analisi dei log ed escalation verso R&D, applicati all’ecosistema Barco CTRL.', 'Certification', '16:00', 1400, array['spec_eng_av']),
  ('KU-E-013', 'BARCO CTRL', 'AV306', 'Barco UniSee', 'È un corso/certificazione tecnica avanzata su Barco UniSee pensato per professionisti che vogliono sviluppare competenze approfondite sui videowall LCD bezel-less di Barco in contesti professionali. Si colloca nel livello Expert del percorso Barco, quindi con focus su installazione e riconfigurazione avanzata, manutenzione, troubleshooting approfondito, raccolta e analisi dei log ed escalation verso R&D applicati all’ecosistema UniSee.', 'Certification', '16:00', 1400, array['spec_eng_av']),
  ('KU-C-065', 'BARCO VIDEO', 'AV102', 'Technical Introduction', 'È un corso e-learning introduttivo tecnico su Barco Event Master, pensato per fornire una panoramica delle specifiche tecniche dei diversi sistemi Event Master e dei relativi card set. Serve a creare una base iniziale utile per comprendere meglio l’architettura della piattaforma di image processing Barco nei contesti live e professionali.', 'E-Learning', '01:00', 0, array['core_av','core_doc']),
  ('KU-E-014', 'BARCO VIDEO', 'AV202', 'E2 Gen2', 'È un corso/certificazione specialistica in aula su Barco Event Master, pensato per tecnici AV, technical director e pre-sales che devono configurare, usare e comprendere in profondità la piattaforma nei live event. Copre hardware Event Master, terminologia video digitale, setup e operation, Toolset, controller EC-30/EC-50, linking con Ex, applicazioni widescreen/multi-screen/LED wall e include esami pratici e teorici per ottenere la qualifica Barco Certified Specialist, valida 2 anni.', 'Certification', '32:00', 2000, array['adv_eng_av']),
  ('KU-E-015', 'BARCO VIDEO', 'AV307', 'E2 Gen2 (Level 2)', 'È un corso avanzato in aula su Barco Event Master E2 Gen2 (Level 2), pensato per chi vuole sviluppare competenze più approfondite sulla piattaforma di image processing per eventi live. Si colloca nel livello Expert del percorso Barco, con focus su configurazione avanzata, gestione operativa e troubleshooting dei sistemi Event Master in contesti professionali.', 'Certification', '24:00', 2400, array['spec_eng_av']),
  ('KU-E-016', 'BARCO VIDEO', 'AV307', 'Event Master Encore3 Certified Specialist', 'È un corso specialistico completo su Barco Encore3 / Event Master, pensato sia per chi conosce già Event Master E2 sia per chi è nuovo nel mondo Barco Image Processing. Fornisce una formazione approfondita sul prodotto attuale Encore3 e, al completamento del percorso di 3 giorni, porta alla certificazione Level 1 Specialist. Il link russo che hai inviato non risulta disponibile, ma il contenuto corrisponde alla pagina Barco del corso Event Master Encore3 Technical Specialist Full / Certified Specialist.', 'Certification', '24:00', 1400, array['spec_eng_av']),
  ('KU-E-017', 'BARCO VIDEO', 'AV203', 'Corso Image Processor presso Comm-Tec', 'Corso organizzato da comm-tec che garantisce una formazione generale sui processori grafici e la loro configurazione.', 'Certification', null, 0, array['adv_eng_av','adv_doc']),
  ('KU-C-066', 'BRIGHTSIGN', 'AV203', 'brightAuthor connected 101', 'Corso base e generico sull''utilizzo dei brightsign.', 'E-Learning', '04:00', 0, array['adv_eng_av','adv_doc']),
  ('KU-C-067', 'CISCO', 'KAPLET101', 'Black Belt New Hire', null, 'E-Learning', null, 0, array['core_av','core_net','core_sec','core_doc']),
  ('KU-C-068', 'CISCO', 'KAPLET101', 'Black Belt (Collaboration) almeno 25 in totale', null, 'E-Learning', null, 0, array['core_av','core_net','core_sec','core_doc']),
  ('KU-C-069', 'CISCO', 'KAPLET101', 'Black Belt (Networking) almeno 25 in totale', null, 'E-Learning', null, 0, array['core_av','core_net','core_sec','core_doc']),
  ('KU-E-018', 'CISCO', 'NET101', 'Cisco Certified Support Technician (CCST) Networking', 'È la certificazione CCST IT Support, pensata per validare competenze entry-level di supporto IT e preparare a ruoli come help desk, end-user support, computer support specialist e IT help desk analyst. Fa parte del percorso Cisco Certified Support Technician e, per ottenerla, bisogna superare un esame core; Cisco indica che non ci sono prerequisiti formali.', 'Certification', null, 125, array['core_net','core_doc']),
  ('KU-E-019', 'CISCO', 'NET101', 'Certified Support Technician (CCST) IT Support', 'È la famiglia di certificazioni Cisco Certified Support Technician (CCST), pensata per ruoli entry-level IT. Valida competenze di base in networking, cybersecurity o IT support, non richiede prerequisiti formali e si ottiene superando un esame core per ciascun percorso. Cisco la presenta anche come primo passo verso certificazioni associate come CCNA o Cisco Certified Cybersecurity Associate.', 'Certification', null, 125, array['core_av','core_net','core_sec','core_doc']),
  ('KU-E-020', 'CISCO', 'NET101', 'Cisco Certified Network Associate (CCNA)', 'È la certificazione Cisco CCNA (Cisco Certified Network Associate), pensata per validare competenze fondamentali in networking, IP connectivity, IP services, security e automazione. È un titolo molto riconosciuto per chi vuole iniziare o consolidare una carriera in ambito reti e IT. Per ottenerla bisogna superare un unico esame, non ci sono prerequisiti formali, anche se Cisco segnala che può essere utile avere 1 o più anni di esperienza pratica con soluzioni Cisco. La certificazione ha validità 3 anni.', 'Certification', null, 300, array['core_net']),
  ('KU-E-021', 'CISCO', 'AV205', 'Cisco Certified Network Professional Collaboration', 'È la certificazione Cisco CCNP Collaboration, pensata per professionisti che vogliono validare competenze avanzate nelle tecnologie di collaborazione, tra cui infrastruttura e design, protocolli, endpoint, applicazioni collaboration e call control. Per ottenerla bisogna superare 2 esami: 1 core exam e 1 concentration exam; non ci sono prerequisiti formali, anche se Cisco indica spesso 3–5 anni di esperienza nel settore. La certificazione ha validità 3 anni.', 'Certification', null, 400, array['adv_eng_av']),
  ('KU-E-022', 'CISCO', 'NET201', 'Cisco Certified Network Professional Enterprise', 'È la certificazione Cisco CCNP Enterprise, pensata per professionisti che vogliono validare competenze avanzate nelle reti enterprise, inclusi infrastructure, virtualization, network assurance, security e automation. Per ottenerla bisogna superare 2 esami: 1 core exam e 1 concentration exam; non ci sono prerequisiti formali, anche se Cisco indica spesso 3–5 anni di esperienza nell’implementazione di soluzioni enterprise. La certificazione ha validità 3 anni.', 'Certification', null, 400, array['adv_eng_net']),
  ('KU-E-023', 'CISCO', 'NET202', 'Cisco Certified Network Professional Wireless', 'È la nuova certificazione Cisco CCNP Wireless, che Cisco introdurrà dal 19 marzo 2026 per riportare in un percorso dedicato le competenze wireless prima incluse nel CCNP Enterprise. È pensata per professionisti che vogliono validare competenze avanzate su reti Wi-Fi enterprise, progettazione, implementazione, troubleshooting e tecnologie moderne come Wi-Fi 6, Wi-Fi 7 e Cisco Meraki.', 'Certification', null, 400, array['adv_eng_net']),
  ('KU-E-024', 'CISCO', 'AV305', 'Cisco Certified Internetwork Expert (CCIE) Collaboration', 'È la certificazione Cisco CCIE Collaboration, pensata per professionisti senior che vogliono validare competenze di livello expert nella progettazione, implementazione, operation e ottimizzazione di soluzioni di collaboration complesse. Copre aree come unified communications, gestione e analytics cloud-connected, hybrid/cloud calling, Webex Contact Center e API. Per ottenerla bisogna superare 2 esami: 1 core exam e 1 practical exam; non ci sono prerequisiti formali, anche se Cisco raccomanda 5–7 anni di esperienza. La certificazione ha validità 3 anni.', 'Certification', null, 400, array['spec_eng_av']),
  ('KU-E-025', 'CISCO', 'NET301', 'Cisco Certified Internetwork Expert (CCIE) Enterprise', 'È la certificazione Cisco CCIE Enterprise Infrastructure, pensata per professionisti senior che vogliono validare competenze di livello expert nelle reti enterprise, dalla progettazione e implementazione fino a operation, ottimizzazione, sicurezza, servizi e automazione. Per ottenerla bisogna superare 2 esami: 1 core exam scritto e 1 lab pratico hands-on; non ci sono prerequisiti formali, anche se Cisco raccomanda 5–7 anni di esperienza. La certificazione ha validità 3 anni.', 'Certification', null, 400, array['spec_eng_net']),
  ('KU-E-026', 'CISCO', 'NET302', 'Cisco Certified Internetwork Expert (CCIE) Enterprise Wireless', 'È la certificazione Cisco CCIE Enterprise Wireless, pensata per professionisti senior che vogliono validare competenze di livello expert nella progettazione, implementazione, operation e ottimizzazione di reti wireless enterprise complesse. Copre aree come architetture wireless, sicurezza, analytics, automazione e programmabilità. Per ottenerla bisogna superare 2 esami: 1 core exam e 1 lab pratico hands-on; non ci sono prerequisiti formali, anche se Cisco raccomanda 5–7 anni di esperienza. La certificazione ha validità 3 anni.', 'Certification', null, 400, array['spec_eng_net']),
  ('KU-C-070', 'CRESTRON', 'AV102', 'Crestron Basics - Commercial', 'È un learning path introduttivo per il mercato commerciale pensato per fornire le competenze essenziali per progettare e installare soluzioni Crestron enterprise-grade. Copre una panoramica dei prodotti Crestron con focus su conferencing e collaboration, video intelligente, distribuzione AV avanzata, networking AV, AV over IP, XiO Cloud, sicurezza e USB, costruendo una base tecnica utile per chi inizia a lavorare con l’ecosistema Crestron.', 'E-Learning', null, 0, array['core_av','core_doc']),
  ('KU-C-071', 'CRESTRON', 'AV102', 'Crestron Commercial Solutions (No Classroom)', 'È un learning path dedicato alle soluzioni Crestron per ambienti commerciali, pensato per sviluppare competenze su progettazione, implementazione e gestione di sistemi AV professionali in contesti corporate. Copre temi come DigitalMedia, room scheduling, sistemi di controllo, AV Framework, switch USB, applicazioni commerciali e design degli spazi, con l’obiettivo di migliorare collaborazione, uniformità d’esperienza e produttività negli ambienti di lavoro.', 'E-Learning', null, 0, array['core_av','core_doc']),
  ('KU-C-072', 'CRESTRON', 'AV102', 'Crestron Certified Technology Architect - Commercial (CTA-C)', 'È un percorso di certificazione avanzato per il mercato commerciale, pensato per AV designer, tecnici e figure technical sales che vogliono approfondire le tecnologie Crestron più evolute. Copre Crestron Basics, software e strumenti, DM NVX, intelligent video e Automate VX, Flex conferencing & collaboration, lighting & shades, soluzioni commerciali e XiO Cloud, con un approccio orientato a progettazione, implementazione e gestione di sistemi AV avanzati; al termine consente di ottenere la certificazione Crestron Certified Technology Architect – Commercial (CTA-C).', 'E-Learning', null, 0, array['core_av','core_doc']),
  ('KU-C-073', 'CRESTRON', 'AV102', 'DM NVX® Technology - Certified Designer', 'È un percorso di certificazione specialistico dedicato alla progettazione di sistemi AVoIP con tecnologie Crestron, pensato per chi vuole approfondire DM NVX, DM NAX e DM NUX. Copre design di soluzioni AV over IP, risorse progettuali, scenari applicativi, utilizzo del PoE, sicurezza di rete, terminologia IT, DM NVX Director e XiO Cloud, con un approccio orientato a progettazione e implementazione di ecosistemi AV su rete; al termine permette di sviluppare competenze avanzate come Certified Designer nell’ambito DM NVX Technology.', 'E-Learning', null, 0, array['core_av','core_doc']),
  ('KU-C-074', 'CRESTRON', 'AV203', 'DM NVX® Technology - Certified Engineer', 'È un percorso di certificazione tecnico-pratico dedicato alla tecnologia DM NVX AV-over-IP, pensato per chi vuole acquisire esperienza concreta nella progettazione, configurazione, deployment e troubleshooting di soluzioni Crestron su rete. Copre l’integrazione di video, audio e USB in ambiente IP, con un approccio orientato all’intero ciclo di vita del sistema, dal concept fino alla messa in esercizio; al termine consente di sviluppare competenze operative avanzate come Certified Engineer nell’ambito DM NVX Technology.', 'E-Learning', null, 0, array['adv_eng_av']),
  ('KU-C-075', 'CRESTRON', 'AV310', 'Intelligent Video - Certified Designer', 'È un percorso di certificazione specialistico dedicato alla progettazione di soluzioni Crestron Intelligent Video con Automate VX, pensato per chi vuole imparare a disegnare e implementare correttamente sistemi di tracking e regia automatica in ambienti diversi. Copre posizionamento di camere e microfoni, criteri progettuali per le varie tipologie di spazio, uso del tool Automate VX Room Designer e generazione del file di progetto per design review e deployment, con un approccio orientato a progettazione accurata e implementazione efficace; al termine consente di ottenere la certificazione Intelligent Video Certified Design (IVC-D).', 'E-Learning', null, 0, array['spec_eng_av']),
  ('KU-C-076', 'CRESTRON', 'AV310', 'Intelligent Video - Certified Engineer', 'È un percorso di certificazione tecnico-pratico dedicato alle soluzioni Crestron Intelligent Video con Automate VX, pensato per chi vuole imparare a configurare, mettere in servizio e risolvere problemi in ambienti meeting ad alto impatto come boardroom e lecture hall. Copre commissioning, troubleshooting, ottimizzazione delle inquadrature, tracciamento del relatore attivo, layout video personalizzati, registrazione e streaming integrati, oltre all’integrazione con piattaforme di videoconferenza esistenti, con un approccio orientato a gestione operativa e implementazione avanzata; al termine consente di ottenere la certificazione Intelligent Video Certified Engineer (IVC-E).', 'E-Learning', null, 0, array['spec_eng_av']),
  ('KU-C-077', 'CRESTRON', 'AV102', 'Technician, Crestron Commercial - Certification', 'È un percorso di certificazione per tecnici AV in ambito commerciale, pensato per chi vuole acquisire le basi per installare, configurare e mettere in servizio soluzioni Crestron complesse. Copre commissioning di sistemi completi, integrazione con apparati di terze parti, terminologia di settore, configurazione dei dispositivi Crestron, uso dei software applicativi e supporto post-installazione, con un approccio orientato a attività operative e avviamento dei sistemi; al termine consente di ottenere la certificazione Technician, Crestron Commercial.', 'E-Learning', null, 0, array['core_av','core_doc']),
  ('KU-C-140', 'CRESTRON', null, 'Crestron Core Track', null, 'E-Learning', null, null, '{}'),
  ('KU-C-141', 'CRESTRON', null, 'Crestron Fundamentals Commercial (CTI-CFC)', null, 'E-Learning', null, null, '{}'),
  ('KU-C-142', 'CRESTRON', null, 'Crestron Network Solutions - Introduzione (CNS-I)', null, 'E-Learning', null, null, '{}'),
  ('KU-C-143', 'CRESTRON', null, 'Crestron Network Solutions - Design (CNS-D)', null, 'E-Learning', null, null, '{}'),
  ('KU-C-144', 'CRESTRON', null, 'DigitalMedia 4K Designer', null, 'E-Learning', null, null, '{}'),
  ('KU-C-078', 'ELMO', 'SEC202', 'Elmo Security', 'E'' Un percorso formativo Tecnico/Pre sales con presentazione prodotti e corso Base /Avanzato di configurazione apparati', 'In-Class', '08:00', 0, array['adv_eng_sec','adv_doc','adv_field']),
  ('KU-C-079', 'EXTRON', 'AV101', 'AV Associate', 'È un programma di certificazione online introduttivo pensato per fornire una solida base sulle tecnologie AV fondamentali e una panoramica dei prodotti e delle applicazioni Extron. Copre temi come networking, controllo di sistema ed elaborazione digitale del segnale, si segue online in autonomia da desktop o mobile e rappresenta anche la base per i percorsi di certificazione avanzati Extron.', 'E-Learning', '27:00', 0, array['core_av','core_doc']),
  ('KU-C-080', 'EXTRON', 'AV202', 'ProDSP Specialist', 'È un programma di certificazione online specialistico pensato per chi vuole approfondire la configurazione, il controllo e l’ottimizzazione di sistemi audio con prodotti Extron ProDSP. Copre l’uso del software DSP Configurator, i criteri di setup e tuning audio, l’impiego di template e blocchi di elaborazione, la validazione delle configurazioni DSP in diverse applicazioni AV, oltre a temi come Dante e VoIP in ambito audio di rete; è indicato per professionisti che installano, configurano e ottimizzano sistemi audio AV.', 'E-Learning', null, 0, array['adv_eng_av']),
  ('KU-C-081', 'EXTRON', 'AV201', 'NetworkAV Specialist', 'È un programma di certificazione online specialistico pensato per chi vuole approfondire la progettazione, il deployment, il commissioning e il troubleshooting di sistemi AV over IP con ecosistema Extron NAV. Copre configurazioni punto-punto e multipunto, best practice d’uso di NAVigator per gestione e controllo sicuri, pianificazione del sistema, sicurezza di rete e workflow operativi, con un approccio orientato a implementazione e gestione di sistemi AV in rete; al termine sviluppa competenze come Network AV Specialist (NAVS).', 'In-Class', null, 0, array['adv_presales_av','adv_eng_av','adv_doc']),
  ('KU-E-027', 'FORTINET', 'NET101', 'NSE 1+2 | Fortinet Certified Fundamentals Cybersecurity', 'È un percorso formativo introduttivo sulla cybersecurity (Fortinet Certified Fundamentals), pensato per fornire una base solida sui concetti fondamentali della sicurezza informatica. Copre il panorama delle minacce, i principi di sicurezza, le tecniche di protezione e le principali tecnologie, con l’obiettivo di preparare a ruoli entry-level o a chi necessita di una comprensione generale della cybersecurity.', 'Certification', null, 0, array['core_sec','core_doc']),
  ('KU-E-028', 'FORTINET', 'NET203', 'NSE 3 | Fortinet Certified Professional Security Operations', 'È un percorso formativo di livello base-intermedio sulla cybersecurity (Fortinet Certified Associate – FCA), pensato per sviluppare competenze operative nella gestione e configurazione dei dispositivi di sicurezza FortiGate.

Il corso copre le funzionalità principali dei firewall Fortinet, incluse attività come configurazione di rete, policy di sicurezza, VPN, controllo accessi, monitoraggio e protezione dalle minacce, con l’obiettivo di fornire una comprensione pratica delle operazioni di sicurezza più comuni. 

È rivolto a professionisti IT e cybersecurity che devono gestire o amministrare infrastrutture di sicurezza, e richiede il superamento di un esame finale (FortiGate Operator) per ottenere la certificazione, valida tipicamente per due anni.', 'Certification', '06:30', 0, array['adv_eng_sec']),
  ('KU-E-029', 'FORTINET', 'NET203', 'NSE 4+5 | Fortinet Certified Professional Security Operations', 'È un percorso formativo di livello intermedio sulla sicurezza operativa, pensato per sviluppare competenze nella gestione, monitoraggio e risposta agli incidenti di cybersecurity. Copre attività come analisi dei log, rilevamento delle minacce e gestione delle operazioni di sicurezza, con l’obiettivo di preparare ruoli operativi in ambito SOC e sicurezza IT.', 'Certification', null, 0, array['adv_eng_sec']),
  ('KU-E-030', 'FORTINET', 'NET203', 'NSE 4+5 | Fortinet Certified Professional Cloud Security Security Operations', 'È un percorso formativo di livello intermedio dedicato alla sicurezza in ambienti cloud, pensato per sviluppare competenze nella protezione di infrastrutture e applicazioni cloud. Copre temi come configurazione della sicurezza, gestione degli accessi, monitoraggio e protezione delle workload, con l’obiettivo di preparare a ruoli operativi nella cloud security.', 'Certification', null, 0, array['adv_eng_sec']),
  ('KU-E-031', 'FORTINET', 'NET203', 'NSE 4+5 | Fortinet Certified Professional SASE Security Operations', 'È un percorso formativo di livello intermedio dedicato all’architettura SASE (Secure Access Service Edge), pensato per sviluppare competenze nella protezione degli accessi a Internet, cloud e applicazioni SaaS. Copre la progettazione, implementazione e gestione di infrastrutture SASE, includendo concetti come accesso sicuro, Zero Trust e sicurezza cloud-based, con l’obiettivo di preparare ruoli tecnici nella network e cloud security.', 'Certification', null, 0, array['adv_eng_sec']),
  ('KU-E-032', 'FORTINET', 'NET203', 'NSE 4+5 | Fortinet Certified Professional Security Operations', 'È un percorso formativo di livello intermedio dedicato alla sicurezza delle reti, pensato per sviluppare competenze nella configurazione, gestione e monitoraggio di infrastrutture di network security. Copre attività operative come deployment di firewall, gestione delle policy, analisi del traffico e protezione delle applicazioni, con l’obiettivo di preparare ruoli tecnici nella network security e amministrazione di sistemi di sicurezza.', 'Certification', null, 0, array['adv_eng_sec']),
  ('KU-E-033', 'FORTINET', 'NET303', 'NSE 6+7 | Fortinet Certified Specialist Security Operations', 'È un percorso formativo avanzato dedicato alla security operations, pensato per sviluppare competenze nella progettazione, gestione e ottimizzazione di infrastrutture SOC. Copre attività come monitoraggio avanzato, analisi e risposta agli incidenti, troubleshooting e automazione delle operazioni di sicurezza, con l’obiettivo di preparare profili senior nella cybersecurity operativa e architettura di sicurezza.', 'Certification', null, 0, array['spec_eng_sec']),
  ('KU-E-034', 'FORTINET', 'NET303', 'NSE 6+7 | Fortinet Certified Specialist Cloud Security Security Operations', 'È un percorso formativo avanzato dedicato alla sicurezza in ambienti cloud, pensato per sviluppare competenze nella progettazione, gestione e ottimizzazione di architetture di cloud security a livello enterprise. Copre attività come design, amministrazione, monitoraggio e troubleshooting di soluzioni di sicurezza per applicazioni cloud pubbliche e private, con l’obiettivo di preparare profili senior nella cloud security e architettura di sicurezza avanzata.', 'Certification', null, 0, array['spec_eng_sec']),
  ('KU-E-035', 'FORTINET', 'NET303', 'NSE 6+7 | Fortinet Certified Specialist SASE Security Operations', 'È un percorso formativo avanzato dedicato all’architettura SASE (Secure Access Service Edge), pensato per sviluppare competenze nella progettazione, gestione e ottimizzazione di infrastrutture di accesso sicuro distribuite. Copre attività come design, deployment, monitoraggio e troubleshooting di soluzioni SASE, includendo componenti come SD-WAN, Zero Trust, secure web gateway e firewall-as-a-service, con l’obiettivo di preparare profili senior nella network e cloud security avanzata', 'Certification', null, 0, array['spec_eng_sec']),
  ('KU-E-036', 'FORTINET', 'NET303', 'NSE 6+7 | Fortinet Certified Specialist Security Operations', 'È un percorso formativo avanzato dedicato alla sicurezza delle reti, pensato per sviluppare competenze nella progettazione, gestione e ottimizzazione di infrastrutture di network security a livello enterprise. Copre attività come design, amministrazione, monitoraggio e troubleshooting di soluzioni avanzate (firewall, SD-WAN, routing e sicurezza integrata), con l’obiettivo di preparare profili senior nella network security e architettura di sicurezza', 'Certification', null, 0, array['spec_eng_sec']),
  ('KU-C-082', 'K-ARRAY', 'AV202', '2-DAY K-EXPERIENCE AT K-ARRAY HQ', null, 'In-Class', '16:00', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-083', 'K-ARRAY', 'AV202', 'K-ARRAY Certified Designer', null, 'E-Learning', '24:00', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-084', 'K-ARRAY', 'AV202', 'K-ARRAY Certified Installer', null, 'E-Learning', '24:00', 0, array['adv_eng_av']),
  ('KU-C-085', 'K-SCAPE', 'AV202', 'KSCAPE WEBINAR SERIES: RAIL S', null, 'E-Learning', '01:00', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-086', 'K-SCAPE', 'AV202', 'KSCAPE APPLICATION WEBINAR SERIES: CORPORATE', null, 'E-Learning', '01:00', 0, array['adv_presales_av']),
  ('KU-C-087', 'K-SCAPE', 'AV202', 'KSCAPE APPLICATION WEBINAR SERIES: HOSPITALITY', null, 'E-Learning', '01:00', 0, array['adv_presales_av']),
  ('KU-C-088', 'KSENIA', 'SEC202', 'Ksenia security', 'E'' Un percorso formativo Tecnico/Pre sales con presentazione prodotti e corso Base /Avanzato di configurazione apparati', 'In-Class', '16:00', 0, array['adv_eng_sec','adv_doc','adv_field']),
  ('KU-C-089', 'MAXHUB', 'AV102', 'MAXHUB XBoard V7 Series', null, 'E-Learning', '01:00', 0, array['core_av','core_doc']),
  ('KU-C-090', 'MILESTONE', 'SEC201', 'XProtect Certified Design Engineer (XCDE)', 'Gli ingegneri di progettazione XProtect progettano soluzioni di sorveglianza per soddisfare le esigenze dei clienti. La valutazione XProtect Certified Design Engineer (XCDE) verifica le tue conoscenze su: Nozioni di base sulla sorveglianza tecnica e video, progettazione del sondaggio del sito, architettura del sistema XProtect, prodotti ed estensioni XProtect, funzionalità di progettazione XProtect, workstation client intelligenti, licenze e assistenza XProtect, best practice per la sicurezza e la sicurezza informatica e gli strumenti e le risorse dei partner XProtect.', 'E-Learning', '16:00', 850, array['adv_presales_sec','adv_eng_sec']),
  ('KU-C-091', 'MILESTONE', 'SEC301', 'XProtect Certified Integration Technician (XCIT)', 'I tecnici di integrazione XProtect installano e configurano installazioni XProtect VMS moderatamente complesse con conteggi delle telecamere di 100-500 telecamere. La valutazione XProtect Certified Integration Technician (MCIT) verifica la tua capacità di eseguire questa attività.', 'E-Learning', '24:00', 1000, array['spec_eng_sec']),
  ('KU-C-092', 'MILESTONE', 'SEC301', 'XProtect Certified Integration Engineer (XCIE)', 'Gli ingegneri di integrazione certificati XProtect installano e configurano complesse installazioni XProtect con un conteggio delle telecamere di circa 100-10.000 telecamere. La valutazione XProtect Certified Integration Engineer (XCIE) verifica la tua conoscenza e capacità di eseguire attività relative a: Best Practice IT e sicurezza, Preparazione della distribuzione XProtect, Installazione XProtect, Impostazioni di configurazione XProtect, Comportamenti di configurazione XProtect, Espansione XProtect, Consegna XProtect e Manutenzione XProtect.', 'E-Learning', '24:00', 1500, array['spec_eng_sec']),
  ('KU-C-093', 'NOTIFIER', 'SEC101', 'Pre-Sales', 'Corso Pre Sales e Sales direttamente dal Distributore', 'In-Class', '08:00', 0, array['core_sec','core_doc']),
  ('KU-C-094', 'NOTIFIER', 'SEC203', 'Security Fire', 'Corso Tecnico Formativo che abilita alla Programmazione base Centrale Notifier', 'In-Class', '08:00', 0, array['adv_doc','adv_field']),
  ('KU-C-095', 'NOTIFIER', 'SEC203', 'Security Fire', 'Corso Tecnico Formativo che abilita alla Programmazione Avanzata Centrale Notifier', 'In-Class', '08:00', 0, array['adv_field']),
  ('KU-C-096', 'NOVASTAR', 'AV102', 'LED Screen Technician', 'È una certificazione introduttiva di livello base del programma Novastar Certified Engineer (NCE), pensata per formare tecnici junior sulle operazioni fondamentali e sulla manutenzione dei LED display. Copre terminologia di settore, architettura dei sistemi LED, componenti hardware, collegamenti, file di configurazione, software di base, tipologie di schermi, interfacce e scenari applicativi, con l’obiettivo di rendere il candidato capace di orientarsi rapidamente nel contesto tecnico dei display LED; è il livello foundation del percorso NCE e costituisce il prerequisito per le certificazioni successive.', 'E-Learning', null, 0, array['core_av','core_doc']),
  ('KU-C-097', 'NOVASTAR', 'AV311', 'Professional in LED Screen Solution Design', 'È una certificazione di livello intermedio del programma Novastar Certified Engineer (NCE), pensata per chi vuole sviluppare competenze nella progettazione di soluzioni per LED screen. È rivolta a professionisti che hanno già ottenuto la certificazione L1, come sales, pre-sales, solution designer e tecnici che vogliono evolvere verso attività di configurazione e design. Copre architetture avanzate di controllo LED, calcolo dei moduli e dei carichi, scelta dei prodotti Novastar, progettazione di topologie di sistema e sviluppo di soluzioni per piccoli e medi progetti LED; richiede NCE L1 e almeno un anno di esperienza nel settore LED.', 'In-Class', null, 0, array['core_av','core_doc','spec_eng_av']),
  ('KU-C-098', 'NOVASTAR', 'AV311', 'Specialist in LED Screen Solution Design', 'È una certificazione avanzata del programma Novastar Certified Engineer (NCE), pensata per formare professionisti capaci di progettare soluzioni complesse di LED display e sistemi di controllo. È rivolta soprattutto a pre-sales engineer, solution designer e figure tecniche con esperienza nel settore, e copre configurazioni multi-sending card, sincronizzazione, integrazione tra LED/LCD/proiezione, selezione della gamma prodotti Novastar e progettazione per scenari complessi come maxi-schermi, forme irregolari, bassa latenza, alta qualità d’immagine, trasmissione a lunga distanza, cluster publishing, 3D e soluzioni 5G; è indicata in particolare per chi ha già una base NCE L2 o almeno tre anni di esperienza nel settore LED.', 'In-Class', null, 0, array['spec_eng_av']),
  ('KU-C-099', 'NOVASTAR', 'AV311', 'Expert in LED Screen Solution Design', 'COMING SOON', 'In-Class', null, 0, array['spec_eng_av']),
  ('KU-C-100', 'NOVASTAR', 'AV311', 'Professional in LED Screen Implementation', 'È una certificazione di livello intermedio del programma Novastar Certified Engineer (NCE), pensata per formare tecnici con competenze pratiche nell’installazione, configurazione e manutenzione di LED display. È rivolta soprattutto a tecnici, post-sales engineer e rental engineer che hanno già ottenuto la certificazione L1, e copre architetture di controllo avanzate, uso dei principali prodotti Novastar, operazioni avanzate in NovaLCT e troubleshooting completo della catena di sistema; al termine consente di gestire in autonomia installazione, debug e manutenzione di base di progetti LED di piccole e medie dimensioni.', 'In-Class', null, 0, array['spec_eng_av']),
  ('KU-C-101', 'NOVASTAR', 'AV311', 'Specialist in LED Screen Implementation', 'È una certificazione avanzata del programma Novastar Certified Engineer (NCE), pensata per formare figure senior specializzate nell’implementazione di sistemi di controllo per LED display complessi. È rivolta soprattutto a technical support engineer, after-sales engineer, rental engineer e professionisti con oltre 3 anni di esperienza o competenze di livello L2, e copre operazioni avanzate in NovaLCT, utilizzo pratico dell’intera gamma prodotti Novastar, configurazioni per scenari complessi come schermi extra-large o irregolari, bassa latenza, trasmissioni a lunga distanza, soluzioni 3D e sistemi con backup completo; al termine consente di operare su progetti LED complessi e su attività di supporto tecnico avanzato.', 'In-Class', null, 0, array['spec_eng_av']),
  ('KU-C-102', 'NOVASTAR', 'AV311', 'Expert in LED Screen Implementation', 'COMING SOON', 'In-Class', null, 0, array['spec_eng_av']),
  ('KU-C-103', 'NOVASTAR', 'AV311', 'Professional in LED Screen Calibration', 'È una certificazione specialistica intermedia del programma Novastar Certified Engineer (NCE), pensata per formare tecnici capaci di eseguire la calibrazione dei LED display. È rivolta soprattutto a technical support engineer, after-sales engineer e rental engineer che hanno già ottenuto la certificazione L1, e copre fondamenti della calibrazione, diverse modalità di correzione, workflow operativi come CLB-Cabinet, CLB-Screen e Calcube, oltre all’analisi dei casi e al troubleshooting; al termine consente di operare in autonomia nella calibrazione di luminosità e colore dei display LED SMD.', 'In-Class', null, 0, array['spec_eng_av']),
  ('KU-C-104', 'NOVASTAR', 'AV311', 'Specialist in LED Screen Calibration', 'È una certificazione avanzata del programma Novastar Certified Engineer (NCE), pensata per formare figure senior specializzate nella calibrazione dei LED display. È rivolta soprattutto a tecnici, post-sales engineer e rental engineer con certificazione NCE L2 o almeno 3 anni di esperienza, e copre calibrazione SMD e COB, schermi irregolari, calibrazione ad alta precisione e full grayscale, uso dei software CLB e Calcube, oltre al troubleshooting delle problematiche di calibrazione; al termine consente di operare in autonomia su servizi avanzati di calibrazione COB e su schermi LED di forma irregolare.', 'In-Class', null, 0, array['spec_eng_av']),
  ('KU-C-105', 'NOVASTAR', 'AV311', 'Expert in LED Screen Calibration', 'COMING SOON', 'In-Class', null, 0, array['spec_eng_av']),
  ('KU-C-106', 'POWERSOFT', 'AV102', 'Powersoft 101I', 'È un breve corso tecnico di taglio pratico dedicato al software ArmoníaPlus, utile per imparare a creare un progetto Install, utilizzare le funzioni di Dynamic Music Distribution e progettare interfacce App e Web View. Il focus è sulle attività di configurazione e design del sistema per la gestione e il controllo della distribuzione musicale.', 'E-Learning', '03:00', 0, array['core_av','core_doc']),
  ('KU-C-107', 'POWERSOFT', 'AV202', 'Powersoft 201i', 'È un corso tecnico on-demand di livello intermedio dedicato ai sistemi Install Powersoft, pensato per chi vuole approfondire la progettazione di progetti avanzati in ArmoníaPlus. Copre la creazione e gestione di sistemi Install più complessi, oltre a temi come audio networking, configurazione di reti e integrazione con controlli di terze parti, ampliando le competenze sviluppate nel corso 101i e fornendo una comprensione più completa del software e delle funzionalità di sistema.', 'E-Learning', '03:00', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-108', 'Q-SYS', 'AV102', 'Q-SYS Architect', 'È un corso introduttivo in aula su Q-SYS Architect, pensato per chi vuole iniziare a progettare sistemi nell’ecosistema Q-SYS senza necessità di competenze di programmazione o commissioning. È indicato per consulenti AV, end user, pre-sales engineer e progettisti, e copre signal flow di base, differenza tra sistemi centralizzati e distribuiti, design di spazi meeting/collaboration e panoramica delle principali famiglie QSC come processing, I/O, amplificatori e diffusori. Non richiede prerequisiti, dura 4 ore in aula e riconosce 2 crediti AVIXA CTS al superamento dell’assessment finale.', 'Webinar (Prase)', '02:00', 0, array['core_av','core_doc']),
  ('KU-C-109', 'Q-SYS', 'AV102', 'Q-SYS Sales Professional', 'È un corso on-demand pensato per figure commerciali e sales, utile per capire come presentare e valorizzare la piattaforma Q-SYS senza richiedere competenze tecniche o esperienza con Q-SYS Designer. Copre i principi della piattaforma, panoramica hardware e software, controllo integrato con audio e video, value proposition cloud-first ed ecosistema partner, con un approccio orientato a vendita e posizionamento della soluzione. Non richiede prerequisiti, dura circa 3 ore e riconosce 1,5 crediti AVIXA CTS al completamento.', 'In-Class', '03:00', 0, array['core_av','core_doc']),
  ('KU-C-110', 'Q-SYS', 'AV102', 'Q-SYS Level 0', 'Corso introduttivo per accedere al Level 1', 'E-Learning', null, 0, array['core_av','core_doc']),
  ('KU-C-111', 'Q-SYS', 'AV202', 'Q-SYS Level 1', 'È un corso tecnico di livello base-intermedio su Q-SYS, pensato per chi vuole imparare a configurare, distribuire e fare troubleshooting dei sistemi sulla piattaforma. Copre Core Manager, Administrator e Configurator, controllo e UCI, audio playback, test & measurement, mixer, soluzioni di conferencing, telephony deployment, monitoraggio cloud e aspetti di sicurezza, con un approccio orientato a commissioning operativo e preparazione all’esame finale; per completarlo è richiesto prima il corso Q-SYS Level Zero.', 'E-Learning', '08:00', 0, array['adv_eng_av','adv_doc']),
  ('KU-C-112', 'Q-SYS', 'AV202', 'Q-SYS Level 2', 'È un corso live di livello intermedio-avanzato su Q-SYS, pensato per chi vuole consolidare le competenze dopo il Level 1 attraverso attività pratiche di deployment, creazione di interfacce utente, introduzione a networking e controllo. Ogni partecipante lavora su Core Q-SYS e periferiche di controllo dedicate, con un approccio fortemente hands-on e un esame finale di troubleshooting basato su scenari reali di installazione. Richiede come prerequisiti Q-SYS Level One e Q-SYS Control 101, può essere seguito in presenza o da remoto ed assegna 8 crediti AVIXA CTS al completamento.', 'In-Class (Prase)', '16:00', 0, array['adv_eng_av']),
  ('KU-C-113', 'Q-SYS', null, 'Q-SYS Quantum', null, 'In-Class', '03:00', null, '{}'),
  ('KU-E-037', 'SHURE', 'AV102', 'Collaboration & Conferencing Certification - Level 1', 'GROUP ID: CCLevel1 | È un percorso introduttivo pensato per team tecnici che gestiscono infrastrutture AV/IT aziendali e per i Channel Partner Shure che supportano i clienti nella scelta delle soluzioni audiovisive più adatte per spazi meeting e ambienti di apprendimento. L’obiettivo è fornire una base chiara per orientarsi tra esigenze tecniche, consulenza e selezione delle tecnologie AV corrette.', 'Certification', '08:00', 0, array['core_av','core_doc']),
  ('KU-E-038', 'SHURE', 'AV202', 'Collaboration & Conferencing Certification - Level 2', 'GROUP ID: CCLevel2 | È un percorso tecnico pensato per tecnici esperti e ingegneri AV/IT che affrontano attività più complesse di progettazione, setup e configurazione dei sistemi, con l’obiettivo di realizzare soluzioni integrate e affidabili. È rivolto a figure con una preparazione già solida e richiede il completamento del Livello 1 come prerequisito per accedere ai corsi.', 'Certification', '08:00', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-E-039', 'SHURE', 'AV202', 'Pro Level 1', 'È un percorso pensato per professionisti audio emergenti, tecnici AV junior, assistenti audio, stagisti e team commerciali, ideale per costruire una base iniziale sulle competenze e sui concetti fondamentali del settore. Si rivolge a figure all’inizio del percorso professionale o che vogliono rafforzare la propria comprensione tecnica per operare con maggiore sicurezza nel mondo audio e AV.', 'Certification', '04:30', 0, array['adv_eng_av']),
  ('KU-E-040', 'SHURE', 'AV202', 'Pro Level 2', 'È un percorso ideale per audio engineer, tecnici live sound (FOH e mix), specialisti corporate e AV coordinator, pensato per figure che operano già in contesti professionali e vogliono consolidare competenze pratiche nella gestione audio. Si rivolge a ruoli coinvolti nella configurazione, ottimizzazione e gestione operativa dei sistemi in ambienti live, corporate ed eventi.', 'Certification', '07:00', 0, array['adv_eng_av']),
  ('KU-E-041', 'SHURE', 'AV308', 'Pro Level 3', 'È un percorso pensato per professionisti AV esperti, RF coordinator, system designer, senior AV engineer e specialisti dell’integrazione, ideale per figure che gestiscono progetti complessi e vogliono approfondire competenze avanzate. Si rivolge a ruoli coinvolti nella progettazione, ottimizzazione e gestione di sistemi AV evoluti, con particolare attenzione agli aspetti di integrazione e coordinamento tecnico.', 'Certification', '14:00', 0, array['spec_eng_av']),
  ('KU-C-114', 'SHURE', 'AV202', 'Microflex Complete Wireless Technical Enablement Training', 'È un corso on-demand di taglio tecnico-specialistico dedicato al sistema Shure Microflex Complete Wireless (MXCW), utile per approfondirne funzionalità, setup e configurazione. Copre caratteristiche e vantaggi, casi d’uso tipici, componenti hardware con montaggio e collegamenti, configurazione di base e configurazione avanzata tramite interfacce web, con un approccio orientato a installazione, commissioning e gestione operativa del sistema.', 'E-Learning', '01:30', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-115', 'SHURE', 'AV202', 'MXA310 Table Array Technical Enablement', 'È un breve corso tecnico di taglio pratico dedicato al microfono da tavolo Shure MXA310, utile per imparare come installarlo e configurarlo correttamente. Il focus è sulle attività essenziali di setup e messa in servizio del dispositivo in ambienti meeting e conferencing.', 'E-Learning', '00:30', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-116', 'SHURE', 'AV202', 'Microflex Wireless neXt 4 and 8 Channel Technical Enablement', 'È un corso tecnico-specialistico on-demand dedicato al sistema Shure Microflex Wireless neXt a 4 e 8 canali, utile per approfondirne funzioni, componenti hardware, interfaccia utente e software Designer. Il percorso, suddiviso in 4 moduli, mostra in modo pratico come configurare il sistema, con casi d’uso, suggerimenti operativi e best practice per l’installazione e la messa in servizio; per ottenere il credito formativo è necessario superare l’esame finale con almeno l’80%.', 'E-Learning', '00:45', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-117', 'SHURE', 'AV102', 'MXA920 Ceiling Array Microphone Technical Enablement', 'È un breve corso tecnico di taglio pratico dedicato al microfono array da soffitto Shure MXA920, utile per imparare come installarlo e configurarlo correttamente. Il focus è sulle attività essenziali di setup e messa in servizio del nuovo modello di punta della gamma di microfoni di rete Shure.', 'E-Learning', '00:45', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-118', 'SHURE', 'AV202', 'Fast Track: BLX Wireless System', 'È un breve corso on-demand di taglio introduttivo dedicato al sistema wireless Shure BLX, utile per capire componenti, funzioni e possibilità d’uso della piattaforma. È pensato per applicazioni come strumenti musicali, fitness e parlato, e fornisce una panoramica pratica delle caratteristiche e capacità del sistema per aiutare a scegliere e usare correttamente la soluzione BLX.', 'E-Learning', '00:15', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-119', 'SHURE', 'AV202', 'SLX-D+ Technical Enablement', 'È un corso tecnico-specialistico on-demand dedicato al sistema wireless Shure SLX-D+, pensato per utenti, tecnici e professionisti audio che vogliono imparare a configurarlo, metterlo in servizio e usarlo con sicurezza. Copre setup e configurazione, oltre a funzioni avanzate come ShowLink Ease, Digital Feedback Reduction, encryption, audio summing e integrazione con Wireless Workbench Mobile, con l’obiettivo di facilitare sia la migrazione da SLX-D sia il primo deployment di SLX-D+ in modo efficace.', 'E-Learning', '00:30', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-120', 'SHURE', 'AV202', 'Fast Track: QLX-D Wireless System', 'È un breve corso on-demand di taglio introduttivo dedicato al sistema wireless digitale Shure QLX-D, utile per conoscere caratteristiche, componenti e funzionamento generale della piattaforma. Il focus è offrire una panoramica chiara del sistema, così da comprenderne meglio le possibilità d’uso in ambito audio professionale.', 'E-Learning', '00:15', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-121', 'SHURE', 'AV202', 'ANX4 Technical Overview', 'È un corso tecnico-specialistico on-demand dedicato al ricevitore wireless scalabile Shure ANX4, pensato per chi vuole imparare a gestire licenze, configurazione hardware e deployment di sistemi wireless ad alta densità di canali. Copre attivazione e trasferimento delle licenze, utilizzo con trasmettitori Axient Digital o ULX-D, setup del ricevitore e workflow operativi, con l’obiettivo di sfruttare al meglio ANX4 in installazioni wireless professionali complesse.', 'E-Learning', '00:35', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-122', 'SHURE', 'AV202', 'Axient Digital PSM Technical Enablement', 'È un corso tecnico-specialistico on-demand dedicato a Shure Axient Digital PSM, pensato per professionisti audio, fonici e staff tecnico che vogliono approfondire in modo pratico e tecnico il sistema. Si basa sulle nozioni introduttive del modulo overview e offre indicazioni più dettagliate su setup, configurazione e utilizzo operativo di Axient Digital PSM, con l’obiettivo di sviluppare una comprensione più completa della piattaforma in contesti professionali.', 'E-Learning', '00:50', 0, array['adv_presales_av','adv_eng_av']),
  ('KU-C-123', 'TECNOFIRE', 'SEC101', 'Corso Pre sales', 'Corso Pre-Sales Prodotti con nozioni sulla normativa antincendio', 'In-Class', '08:00', 0, array['core_sec','core_doc']),
  ('KU-C-124', 'TECNOFIRE', 'SEC203', 'Corso Tecnico 1 Livello', 'Corso Tecnico programmazione Base Centrale Incendio', 'In-Class', '08:00', 0, array['adv_doc','adv_field']),
  ('KU-C-125', 'TECNOFIRE', 'SEC203', 'Corso Tecnico 2 Livello', 'Corso Tecnico programmazione Avanzato Centrale Incendio', 'In-Class', '08:00', 0, array['adv_field']),
  ('KU-C-126', 'TELEVIC', 'AV102', 'Meeting Foundamentals', 'È un breve corso e-learning introduttivo dedicato ai fondamenti dei sistemi di conferenza, utile per capire cosa sia un conference system, quali siano i diversi tipi di meeting e quali componenti siano necessari per realizzare una sala conferenze efficace. Il percorso fornisce una panoramica delle funzionalità principali e delle possibili configurazioni, aiutando a orientarsi tra le esigenze tipiche degli ambienti meeting e le soluzioni tecnologiche disponibili.', 'E-Learning', '01:00', 0, array['core_av']),
  ('KU-C-127', 'TELEVIC', 'AV102', 'Televic Foundation', 'È un breve corso e-learning introduttivo dedicato alle soluzioni Televic per meeting e conferenze, utile per comprendere l’azienda, la sua visione e il portafoglio prodotti. Il percorso offre una panoramica delle tecnologie Televic, delle principali linee di prodotto e delle funzionalità di smart audio e controllo, con l’obiettivo di aiutare a identificare e applicare le soluzioni più adatte ai diversi scenari di meeting e conferencing.', 'E-Learning', '01:00', 0, array['core_av']),
  ('KU-C-128', 'TELEVIC', 'AV309', 'Technical Training Level 1', null, null, null, 0, array['spec_eng_av']),
  ('KU-C-129', 'TELEVIC', 'AV309', 'Technical Training Level 2', null, null, null, 0, array['spec_eng_av']),
  ('KU-C-130', 'YAMAHA', 'AV101', 'General Knowledge | Beginner | 1. Sound and Hearing Basics', 'È un breve corso introduttivo sui principi fondamentali dell’audio, pensato per fornire una base chiara su come viene prodotto il suono, come si propagano le onde sonore e come funziona la percezione uditiva umana. Il percorso aiuta a comprendere i concetti essenziali dell’acustica e dell’audio, risultando utile sia per principianti sia per professionisti che vogliono rafforzare le proprie conoscenze tecniche.', 'E-Learning', '00:30', 0, array['core_av']),
  ('KU-C-131', 'YAMAHA', 'AV101', 'General Knowledge | Beginner | 2. Basics of Sound Wave', 'È un breve corso introduttivo sulle onde sonore e sull’acustica, pensato per fornire una base solida sui principi fisici del suono. Copre temi come proprietà delle onde, frequenza, ampiezza, fase, interazioni tra onde e tipologie di onde sonore, con l’obiettivo di sviluppare una comprensione utile sia per chi inizia sia per chi opera in ambiti come audio engineering, produzione musicale e discipline tecniche correlate.', 'E-Learning', '00:45', 0, array['core_av']),
  ('KU-C-132', 'YAMAHA', 'AV101', 'General Knowledge | Beginner | 3. Sound intensity, loudness, and decibels', 'È un breve corso introduttivo dedicato a intensità sonora, percezione del volume e decibel, pensato per fornire una base chiara sia sugli aspetti fisici sia su quelli percettivi del suono. Copre la differenza tra forza del suono e loudness, il modo in cui l’orecchio umano elabora i segnali audio, il range dinamico, oltre ai concetti di esponenti, logaritmi e definizione del decibel, fondamentali per comprendere correttamente le misure audio.', 'E-Learning', '00:30', 0, array['core_av']),
  ('KU-C-133', 'YAMAHA', 'AV101', 'General Knowledge | Beginner | 4. Sound Intensity and Loudness: Levels and Calculations', 'È un breve corso introduttivo di taglio tecnico dedicato al concetto di livello in acustica, utile per collegare in modo pratico pressione sonora, intensità sonora e loudness percepita. Copre SPL e valori di riferimento, rapporto tra pressione e intensità, curve di uguale sensazione sonora, filtri di pesatura come l’A-weighting, calcoli in decibel e principali scale audio come dBu, dBV e dBFS, con l’obiettivo di fornire una comprensione chiara e applicabile ai contesti audio reali.', 'E-Learning', '00:45', 0, array['core_av']),
  ('KU-C-134', 'YAMAHA', 'AV101', 'General Knowledge | Advanced | Speech Intelligibility: Can You Hear Me?', 'È un breve corso introduttivo dedicato all’intelligibilità del parlato, utile per capire perché una comunicazione chiara dipenda non solo dal sistema AV, ma anche dalle caratteristiche dell’ambiente in cui viene utilizzato. Spiega come si misura l’intelligibilità e quali interventi possono contribuire a migliorarla, offrendo una base pratica per progettare e valutare meglio spazi e soluzioni audio.', 'E-Learning', '00:55', 0, array['core_av']),
  ('KU-C-135', 'YAMAHA', null, 'General Knowledge | Advanced | Connecting AES67 Devices', null, 'E-Learning', '00:15', null, '{}'),
  ('KU-C-136', 'YAMAHA', null, 'Distributed Audio​ and Public Address​ Courses | Beginner | Yamaha Certified ProAV Specialist - Level 1', null, 'E-Learning', '01:00', null, '{}'),
  ('KU-C-137', 'YAMAHA', null, 'Distributed Audio​ and Public Address​ Courses | Beginner | Better Sound for Commercial Installations', null, 'E-Learning', '01:30', null, '{}'),
  ('KU-C-138', 'YAMAHA', null, 'DM3 Series: Digital Mixing Console', null, 'E-Learning', '01:30', null, '{}'),
  ('KU-C-139', 'YAMAHA', null, 'DM7 Series: Digital Mixing Console', null, 'E-Learning', '03:00', null, '{}')
on conflict (id) do update set
  brand       = excluded.brand,
  gruppo      = excluded.gruppo,
  nome        = excluded.nome,
  descrizione = excluded.descrizione,
  erogazione  = excluded.erogazione,
  durata      = excluded.durata,
  prezzo      = excluded.prezzo,
  paths       = excluded.paths;

-- ============================================================
-- 4. Corsi ritirati
--    Non si cancellano: le certificazioni e le assegnazioni già
--    registrate devono continuare a trovare il loro corso.
--    Sta qui e non nella INSERT sopra perché l'upsert non tocca `attivo`:
--    così rilanciare lo script non li fa tornare in catalogo.
-- ============================================================

-- KU-C-034 "Avigilon Unity Video" (in aula, 8h): Kaplet lo considera un
-- doppione di KU-C-033 "Avigilon Unity Video8" (e-learning, 21h).
update public.corsi_catalogo set attivo = false where id = 'KU-C-034';

-- Controllo finale: 183 in tabella, 182 ancora in catalogo
select
  count(*)                          as corsi_in_tabella,
  count(*) filter (where attivo)    as corsi_in_catalogo,
  count(*) filter (where not attivo) as corsi_ritirati
from public.corsi_catalogo;
